window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_09", [
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. वैदिक एवं आधुनिक नदियाँ के अंतर्गत 'कुभा' का ऐतिहासिक संबंध 'झेलम' से था।\n2. वैदिक शब्दावली एवं उपनिषद के अंतर्गत 'गोधूम' का ऐतिहासिक संबंध 'मुद्रा/मूल्य की इकाइयाँ' से था।\n3. मंदसौर अभिलेख रेशम बुनकरों (पट्टवाय श्रेणी) की समृद्धि का वर्णन करता है और यह गुप्त सम्राट समुद्रगुप्त द्वारा ताम्रपत्र पर लिखवाया गया था।\n4. अठारह लघु उपदेशात्मक ग्रंथों के समूह को 'पदिनेणकीलकणक्कु' कहा जाता है जिसमें तिरुवल्लुवर का नीतिशास्त्र ग्रंथ 'तिरुकुरल' भी सम्मिलित है।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (अठारह लघु उपदेशात्मक ग्रंथों के समूह को 'पदिनेणकीलकणक्कु' कहा जाता है जिसमें तिरुवल्लुवर का नीतिशास्त्र ग्रंथ 'तिरुकुरल' भी सम्मिलित है।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक एवं आधुनिक नदियाँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सदानीरा : झेलम\n2. वितस्ता : चिनाब\n3. असिक्नी : काबुल\n4. परुष्णी : रावी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: ऋग्वेद में रावी नदी को 'परुष्णी' कहा गया है जिसके तट पर दाशराज्ञ युद्ध हुआ। (अन्य सही युग्म: सदानीरा→गंडक, वितस्ता→झेलम, असिक्नी→चिनाब)।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सुत्कागेंडोर : सतलज नदी\n2. रोपड़ : चिनाब नदी\n3. मांडा : घग्घर नदी\n4. रंगपुर : मादर/भादर नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: रंगपुर (गुजरात) भादर (मादर) नदी के किनारे स्थित था जहाँ से धान की भूसी मिली। (अन्य सही युग्म: सुत्कागेंडोर→दाश्क नदी, रोपड़→सतलज नदी, मांडा→चिनाब नदी)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्रसिद्ध तमिल महाकाव्य 'शिलप्पादिकारम्' (कोवलन व कण्णगी की कथा) की रचना मणिवण्णन नामक चोल सम्राट द्वारा 12वीं सदी में की गई।\nकथन-2: सुत्कागेंडोर बलूचिस्तान में दाश्क नदी के किनारे स्थित सैंधव सभ्यता का सबसे पश्चिमी छोर था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('शिलप्पादिकारम्' की रचना चेर शासक सेनगुट्टुवन के भाई इलंगो आदिगल ने संगम काल में की थी जिसमें कण्णगी (पत्नी पूजा) का वर्णन है।)। कथन-2 सत्य है (सुत्कागेंडोर बलूचिस्तान में दाश्क नदी के किनारे स्थित सैंधव सभ्यता का सबसे पश्चिमी छोर था।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. वैदिक एवं आधुनिक नदियाँ के अंतर्गत 'कुभा' का ऐतिहासिक संबंध 'झेलम' से था।\n2. संगम साहित्य को भावना के आधार पर 'अहम्' (प्रेम संबंधी) और 'पुरम्' (युद्ध व वीरता संबंधी) दो मुख्य श्रेणियों में बाँटा गया है।\n3. वैदिक शब्दावली एवं उपनिषद के अंतर्गत 'गोधूम' का ऐतिहासिक संबंध 'मुद्रा/मूल्य की इकाइयाँ' से था।\n4. मंदसौर अभिलेख रेशम बुनकरों (पट्टवाय श्रेणी) की समृद्धि का वर्णन करता है और यह गुप्त सम्राट समुद्रगुप्त द्वारा ताम्रपत्र पर लिखवाया गया था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (संगम साहित्य को भावना के आधार पर 'अहम्' (प्रेम संबंधी) और 'पुरम्' (युद्ध व वीरता संबंधी) दो मुख्य श्रेणियों में बाँटा गया है।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. शिलप्पादिकारम् : तिरुवल्लुवर\n2. तिरुक्कुरल : ब्रह्मगुप्त\n3. ब्रह्मस्फुटसिद्धांत : विशाखदत्त\n4. दशकुमारचरितम् : दण्डी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: पल्लव दरबारी दण्डी ने 'दशकुमारचरितम्' व अलंकार ग्रंथ 'काव्यादर्श' की रचना की। (अन्य सही युग्म: शिलप्पादिकारम्→इलंगो आदिगल, तिरुक्कुरल→तिरुवल्लुवर, ब्रह्मस्फुटसिद्धांत→ब्रह्मगुप्त)।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अहं ब्रह्मास्मि : गेहूँ\n2. गोधूम : गायों के लिए युद्ध / खोज\n3. गविष्टि : गाय (न मारे जाने योग्य)\n4. तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु) : छान्दोग्य उपनिषद","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: छान्दोग्य उपनिषद में ऋषि उद्दालक आरुणि और श्वेतकेतु के मध्य 'तत्त्वमसि' संवाद वर्णित है। (अन्य सही युग्म: अहं ब्रह्मास्मि→बृहदारण्यक उपनिषद, गोधूम→गेहूँ, गविष्टि→गायों के लिए युद्ध / खोज)।"},
  {"q":"ऐतिहासिक संदर्भ में 'रामायण (24,000 श्लोक, वाल्मीकि — आदि काव्य); महाभारत (1 लाख श्लोक — 'जय संहिता' व 'शतसाहस्री संहिता'); 18 पुराण' (प्रमुख संरचना तथ्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["महाकाव्य, स्मृतियाँ एवं पुराण साहित्य","ऋग्वैदिक प्रशासनिक एवं सामाजिक शब्दावली","उत्तर-वैदिक काल के रत्निन एवं कर अधिकारी","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)"],"correct":0,"explanation":"मिताक्षरा परंपरा के अंतर्गत पुत्र को जन्म लेते ही पैतृक संपत्ति में अधिकार मिलता था जबकि बंगाल में प्रचलित दायभाग में पिता की मृत्यु के बाद अधिकार मिलता था।"},
  {"q":"ऐतिहासिक संदर्भ में 'विदथ (सबसे प्राचीन सभा), सभा (श्रेष्ठ जनों की), समिति (सामान्य जनसभा)' (संस्थाएँ एवं पद) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","उत्तर-वैदिक काल के रत्निन एवं कर अधिकारी","ऋग्वैदिक प्रशासनिक एवं सामाजिक शब्दावली","महाकाव्य, स्मृतियाँ एवं पुराण साहित्य"],"correct":2,"explanation":"ऋग्वेद में 'अघन्या' (न मारे जाने योग्य) शब्द गाय के लिए तथा 'तक्षन' बढ़ई व 'अयस' ताँबा/कांसा धातु के लिए प्रयुक्त हुआ है।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. ब्रह्मस्फुटसिद्धांत : कल्हण\n2. मृच्छकटिकम् : शूद्रक\n3. राजतरंगिणी : वराहमिहिर\n4. वृहत्संहिता : विशाखदत्त","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: राजा शूद्रक कृत 'मृच्छकटिकम्' में ब्राह्मण व्यापारी चारुदत्त और गणिका वसंतसेना की कथा है। (अन्य सही युग्म: ब्रह्मस्फुटसिद्धांत→ब्रह्मगुप्त, राजतरंगिणी→कल्हण, वृहत्संहिता→वराहमिहिर)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: संगम काल में पश्चिमी तट पर स्थित 'अरिकमेडु' बंदरगाह से मुगलकालीन तोपखाने व अरबी अभिलेख प्राप्त हुए हैं।\nकथन-2: रोपड़ स्वतंत्रता के पूर्व 1921 में उत्खनित पहला स्थल था और यह गोदावरी नदी के किनारे स्थित था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) अरिकमेडु (पुडुचेरी के पास, पूर्वी तट पर) रोमन व्यापारिक बस्ती (एरेटाइन मृदभांड, एम्फोरा जार, रोमन सिक्के) के लिए प्रसिद्ध था जिसे पेरिप्लस में 'पोडुके' कहा गया है। (2) रोपड़ पंजाब में सतलज नदी के तट पर स्थित था और स्वतंत्रता के बाद उत्खनित पहला सैंधव स्थल (1953-56) था।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मांडा : दाश्क नदी\n2. सुत्कागेंडोर : सतलज नदी\n3. हड़प्पा : रावी नदी\n4. रोपड़ : सिन्धु नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: हड़प्पा पुरास्थल रावी नदी के बाएँ तट पर स्थित था। (अन्य सही युग्म: मांडा→चिनाब नदी, सुत्कागेंडोर→दाश्क नदी, रोपड़→सतलज नदी)।"},
  {"q":"संगमकालीन चेर, चोल एवं पांड्य राज्य तथा प्रमुख बंदरगाह — इसके संबंध में 'राजचिह्न एवं राजधानियाँ' कौन/क्या था?","options":["चेर (धनुष-बाण, वंजि, बंदरगाह मुजिरिस); चोल (बाघ, उरैयूर/पुहार); पांड्य (मछली/कार्प, मदुरै, बंदरगाह कोरकई)","भारतीय उपमहाद्वीप में कृषि (गेहूँ-जौ) व पशुपालन के प्राचीनतम प्रमाण","वेलालर (धनी कृषक), कड़ैसियर (कृषि मजदूर), अरसर (शासक वर्ग), एनादी (सेनापति की उपाधि)","पुरापाषाण से मध्यपाषाण काल के प्राचीनतम शैलचित्र"],"correct":0,"explanation":"अनाम नाविक की पुस्तक 'पेरिप्लस ऑफ द एरिथ्रियन सी' तथा प्लिनी के विवरण में रोम से भारत की ओर स्वर्ण के भारी प्रवाह पर चिंता जताई गई है।"},
  {"q":"ऐतिहासिक संदर्भ में 'R-37 कब्रिस्तान, 6-6 की दो पंक्तियों में अन्नागार व बलुआ पत्थर का धड़' (प्रमुख पुरातात्विक साक्ष्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["हड़प्पा (मांटगोमरी/साहीवाल, पंजाब)","लोथल (अहमदाबाद, गुजरात)","कालीबंगा (हनुमानगढ़, राजस्थान)","मोहनजोदड़ो (लरकाना, सिन्ध)"],"correct":0,"explanation":"रावी नदी के बाएँ तट पर स्थित हड़प्पा (खोज 1921, दयाराम साहनी) से श्रमिक आवास, 12 कक्षों का अन्नागार, R-37 कब्रिस्तान और मातृदेवी की मृण्मूर्तियाँ मिलीं।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु सभ्यता के साक्ष्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. शैलकृत जल जलाशय व साइनबोर्ड : चन्हूदड़ो\n2. लिपस्टिक व बिना दुर्ग का औद्योगिक नगर : मोहनजोदड़ो\n3. राख के टीले (पिकलिहल, उत्नूर) : दक्षिण भारत (कर्नाटक-आंध्र)\n4. कांस्य की नर्तकी : आहार (राजस्थान)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: दक्षिण भारत के पिकलिहल, उत्नूर व कुपगल से नवपाषाण कालीन पशुपालकों के राख के टीले मिले। (अन्य सही युग्म: शैलकृत जल जलाशय व साइनबोर्ड→धौलावीरा, लिपस्टिक व बिना दुर्ग का औद्योगिक नगर→चन्हूदड़ो, कांस्य की नर्तकी→मोहनजोदड़ो)।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अघन्या : कोषाध्यक्ष\n2. संगृहीता : मुद्रा/मूल्य की इकाइयाँ\n3. गविष्टि : गायों के लिए युद्ध / खोज\n4. निष्क व शतमन : गेहूँ","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: ऋग्वेद में युद्ध के लिए 'गविष्टि' (गायों की खोज) शब्द प्रयुक्त हुआ है। (अन्य सही युग्म: अघन्या→गाय (न मारे जाने योग्य), संगृहीता→कोषाध्यक्ष, निष्क व शतमन→मुद्रा/मूल्य की इकाइयाँ)।"},
  {"q":"ऐतिहासिक संदर्भ में 'पतंजलि ('महाभाष्य'), भर्तृहरि ('वाक्यपदीय'), अमरसिंह ('अमरकोश' — संस्कृत पर्यायवाची), कामंदक ('नीतिसार')' (प्रमुख ग्रंथ एवं रचयिता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["प्राचीन भारतीय शिक्षा, व्याकरण व कोश साहित्य","प्राचीन भारतीय गणित, खगोल व चिकित्सा वैज्ञानिक","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)"],"correct":0,"explanation":"भास को संस्कृत का प्रथम प्रसिद्ध नाटककार माना जाता है जिनके 13 नाटक (जैसे स्वप्नवासवदत्तम्, प्रतिज्ञायौगंधरायण) टी. गणपति शास्त्री ने खोजे।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. महाजनपद एवं राजधानियाँ के अंतर्गत 'मत्स्य महाजनपद' का ऐतिहासिक संबंध 'राजपुर (हाटक)' से था।\n2. संगम काल में युद्ध में वीरगति पाने वाले नायकों की स्मृति में 'वीरकल' (नडुकल — नायक प्रस्तर स्मारक) स्थापित करने की परंपरा प्रचलित थी।\n3. प्राचीन ग्रंथ एवं रचयिता के अंतर्गत 'अष्टाध्यायी' का ऐतिहासिक संबंध 'पतंजलि' से था।\n4. उत्तर-वैदिक काल में 'सूत' (रथकार) तथा 'ग्रामणी' का पद पूर्णतः समाप्त हो गया और स्त्रियों को उपनयन का पूर्ण अधिकार मिल गया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (संगम काल में युद्ध में वीरगति पाने वाले नायकों की स्मृति में 'वीरकल' (नडुकल — नायक प्रस्तर स्मारक) स्थापित करने की परंपरा प्रचलित थी।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अतिथि देवो भव : मुद्रा/मूल्य की इकाइयाँ\n2. निष्क व शतमन : बृहदारण्यक उपनिषद\n3. अहं ब्रह्मास्मि : कोषाध्यक्ष\n4. गोधूम : गेहूँ","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: वैदिक संस्कृत साहित्य में 'गोधूम' गेहूँ तथा 'व्रीहि' चावल के लिए प्रयुक्त होता था। (अन्य सही युग्म: अतिथि देवो भव→तैत्तिरीय उपनिषद, निष्क व शतमन→मुद्रा/मूल्य की इकाइयाँ, अहं ब्रह्मास्मि→बृहदारण्यक उपनिषद)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. वृहत्संहिता : हेमचंद्र (कलिकाल सर्वज्ञ)\n2. मत्तविलासप्रहसन : महेंद्रवर्मन प्रथम\n3. परिशिष्टपर्वन् : सीतलै सतनार\n4. मणिमेखलै : शूद्रक","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: कांची के पल्लव नरेश महेंद्रवर्मन I ने 'मत्तविलासप्रहसन' नामक संस्कृत हास्य नाटक लिखा। (अन्य सही युग्म: वृहत्संहिता→वराहमिहिर, परिशिष्टपर्वन्→हेमचंद्र (कलिकाल सर्वज्ञ), मणिमेखलै→सीतलै सतनार)।"},
  {"q":"ऐतिहासिक संदर्भ में 'उत्तर: मांडा (चिनाब); दक्षिण: दैमाबाद (प्रवरा); पूर्व: आलमगीरपुर (हिंडन); पश्चिम: सुत्कागेंडोर (दाश्क नदी)' (सीमांत स्थल एवं नदियाँ) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","सिन्धु घाटी की लिपि, मुहरें एवं तौल प्रणाली","सैंधव स्थलों के क्षेत्रीय विस्तार (उत्तरी, दक्षिणी, पूर्वी, पश्चिमी सीमा)","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)"],"correct":2,"explanation":"दैमाबाद (महाराष्ट्र) से कांस्य निर्मित रथ (बैल जुता हुआ), गैंडा, हाथी और भैंसे की सुंदर मूर्तियाँ मिली हैं। बलूचिस्तान में सुत्कागेंडोर तटीय व्यापार चौकी थी।"},
  {"q":"ऐतिहासिक संदर्भ में 'परुष्णी (रावी), असिक्नी (चिनाब), वितस्ता (झेलम), शतुद्रि (सतलज), विपाशा (व्यास)' (प्रमुख नदी युग्म) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["ऋग्वैदिक नदियों के प्राचीन नाम","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","बुर्जहोम (श्रीनगर, जम्मू-कश्मीर)"],"correct":0,"explanation":"सप्त-सैंधव प्रदेश की नदियों में क्रुमु (कुर्रम), कुभा (काबुल), सुवास्तु (स्वाति), सदानीरा (गंडक) और दृषद्वती (घग्घर) भी सम्मिलित थीं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. पाँचवें वृहद शिलालेख में अशोक ने सर्वप्रथम धम्म महामात्रों की नियुक्ति का उल्लेख किया।\n2. अशोक के समय पाटलिपुत्र के अशोकाराम विहार में हुई तृतीय संगीति में अभिधम्म पिटक जोड़ा गया और त्रिपिटक पूर्ण हुए।\n3. संगम काल में पश्चिमी तट पर स्थित 'अरिकमेडु' बंदरगाह से मुगलकालीन तोपखाने व अरबी अभिलेख प्राप्त हुए हैं।\n4. ऋग्वैदिक नदी असिक्नी को आधुनिक समय में चिनाब नदी कहते हैं।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: अरिकमेडु (पुडुचेरी के पास, पूर्वी तट पर) रोमन व्यापारिक बस्ती (एरेटाइन मृदभांड, एम्फोरा जार, रोमन सिक्के) के लिए प्रसिद्ध था जिसे पेरिप्लस में 'पोडुके' कहा गया है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: संगम ग्रंथ 'एत्तुत्तोगै' केवल वैदिक कर्मकांड और हवन विधियों के संस्कृत मंत्रों का अनुवाद मात्र है।\nकथन-2: प्रसिद्ध तमिल महाकाव्य 'शिलप्पादिकारम्' (कोवलन व कण्णगी की कथा) की रचना मणिवण्णन नामक चोल सम्राट द्वारा 12वीं सदी में की गई।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'एत्तुत्तोगै' विशुद्ध तमिल काव्य संकलन है जो प्राचीन दक्षिण भारतीय समाज, प्रेम, युद्ध और व्यापार का प्राथमिक ऐतिहासिक स्रोत है। (2) 'शिलप्पादिकारम्' की रचना चेर शासक सेनगुट्टुवन के भाई इलंगो आदिगल ने संगम काल में की थी जिसमें कण्णगी (पत्नी पूजा) का वर्णन है।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. महाभाष्य : इलंगो आदिगल\n2. शिलप्पादिकारम् : महेंद्रवर्मन प्रथम\n3. मत्तविलासप्रहसन : शूद्रक\n4. ब्रह्मस्फुटसिद्धांत : ब्रह्मगुप्त","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: भीनमाल (राजस्थान) के गणितज्ञ ब्रह्मगुप्त ने 628 ई. में 'ब्रह्मस्फुटसिद्धांत' रचा। (अन्य सही युग्म: महाभाष्य→पतंजलि, शिलप्पादिकारम्→इलंगो आदिगल, मत्तविलासप्रहसन→महेंद्रवर्मन प्रथम)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: संगम काल में पश्चिमी तट पर स्थित 'अरिकमेडु' बंदरगाह से मुगलकालीन तोपखाने व अरबी अभिलेख प्राप्त हुए हैं।\nकथन-2: गुप्तकालीन बंगाल के ताम्रपत्रों (जैसे दामोदरपुर, धनैदह) में 'कुल्यवाप', 'द्रोणवाप' और 'आढ़वाप' का प्रयोग भूमि क्षेत्रफल की माप के रूप में हुआ है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (अरिकमेडु (पुडुचेरी के पास, पूर्वी तट पर) रोमन व्यापारिक बस्ती (एरेटाइन मृदभांड, एम्फोरा जार, रोमन सिक्के) के लिए प्रसिद्ध था जिसे पेरिप्लस में 'पोडुके' कहा गया है।)। कथन-2 सत्य है (गुप्तकालीन बंगाल के ताम्रपत्रों (जैसे दामोदरपुर, धनैदह) में 'कुल्यवाप', 'द्रोणवाप' और 'आढ़वाप' का प्रयोग भूमि क्षेत्रफल की माप के रूप में हुआ है।)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मत्तविलासप्रहसन : गुप्तकाल (बोवर पांडुलिपि)\n2. नवनीतकम (आयुर्वेद ग्रंथ) : भास\n3. विक्रमांकदेवचरित : बिल्हण\n4. स्वप्नवासवदत्तम् : विष्णु शर्मा","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: कश्मीरी कवि बिल्हण ने कल्याणी के चालुक्य राजा विक्रमादित्य VI के दरबार में यह महाकाव्य लिखा। (अन्य सही युग्म: मत्तविलासप्रहसन→महेंद्रवर्मन प्रथम, नवनीतकम (आयुर्वेद ग्रंथ)→गुप्तकाल (बोवर पांडुलिपि), स्वप्नवासवदत्तम्→भास)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. हस्त्यायुर्वेद : इलंगो आदिगल\n2. शिलप्पादिकारम् : महेंद्रवर्मन प्रथम\n3. मत्तविलासप्रहसन : ब्रह्मगुप्त\n4. राजतरंगिणी : कल्हण","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: कल्हण ने 1148-50 ई. में संस्कृत श्लोकों में कश्मीर का क्रमबद्ध इतिहास 'राजतरंगिणी' लिखा। (अन्य सही युग्म: हस्त्यायुर्वेद→पालकाप्य, शिलप्पादिकारम्→इलंगो आदिगल, मत्तविलासप्रहसन→महेंद्रवर्मन प्रथम)।"},
  {"q":"'तीन तमिल संगम एवं प्रमुख संगम साहित्य' के ऐतिहासिक संदर्भ में 'प्रमुख महाकाव्य व नीति ग्रंथ' निम्नलिखित में से क्या है?","options":["'तिरुकुरल' (तिरुवल्लुवर — तमिलों की बाइबिल), 'शिलप्पादिकारम्' (इलंगो आदिगल), 'मणिमेखलै' (सीतलै सतनार)","डॉ. वी.एस. वाकणकर (1957-58) द्वारा खोजा गया","नवपाषाण काल (लगभग 7000 ई.पू.), बोलन दर्रे के समीप","'पट्टिनप्पालै' में कावेरीपट्टनम (पुहार) के व्यापार व करिकाल चोल का सजीव वर्णन मिलता है"],"correct":0,"explanation":"संगम काल में तिनै (पाँच भौगोलिक क्षेत्र): कुरिंजी (पहाड़), मुल्लै (चरागाह), मरुतम (उपजाऊ मैदान), नेथल (तटीय) और पालै (शुष्क) वर्णित हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — षड्दर्शन एवं प्रवर्तक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. योग दर्शन : महर्षि गौतम (अक्षपाद)\n2. न्याय दर्शन : महर्षि कपिल\n3. सांख्य दर्शन : महर्षि जैमिनी\n4. वैशेषिक दर्शन : महर्षि कणाद (उलूक)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: महर्षि कणाद ने वैशेषिक दर्शन में द्रव्य, गुण, कर्म व परमाणुवाद की नींव रखी। (अन्य सही युग्म: योग दर्शन→महर्षि पतंजलि, न्याय दर्शन→महर्षि गौतम (अक्षपाद), सांख्य दर्शन→महर्षि कपिल)।"},
  {"q":"ऐतिहासिक संदर्भ में 'शिक्षा (ध्वनि), कल्प (कर्मकांड), व्याकरण (पाणिनि), निरुक्त (यास्क), छंद (पिंगल), ज्योतिष (लगध)' (छह वेदांग) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","वेदांग, सूत्र साहित्य एवं संस्कार","सामवेद, यजुर्वेद एवं अथर्ववेद","ऋग्वेद एवं इसके प्रमुख मंडल"],"correct":1,"explanation":"गृह्यसूत्रों में विवाह के आठ प्रकारों (चार प्रशस्त—ब्रह्म, दैव, आर्ष, प्राजापत्य; चार अप्रशस्त—असुर, गंधर्व, राक्षस, पैशाच) व 16 संस्कारों का वर्णन मिलता है।"},
  {"q":"ऐतिहासिक संदर्भ में 'वेलालर (धनी कृषक), कड़ैसियर (कृषि मजदूर), अरसर (शासक वर्ग), एनादी (सेनापति की उपाधि)' (प्रमुख सामाजिक व कृषि पद) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["संगमकालीन सामाजिक वर्ग, देवपूजा एवं कृषि शब्दावली","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","संगमकालीन चेर, चोल एवं पांड्य राज्य तथा प्रमुख बंदरगाह","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)"],"correct":0,"explanation":"संगम काल में 'कावेरीपट्टनम' (पुहार) चोलों का प्रमुख बंदरगाह था जहाँ से मलमल व मसालों का अंतरराष्ट्रीय व्यापार होता था।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु सभ्यता के साक्ष्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लिपस्टिक व बिना दुर्ग का औद्योगिक नगर : चन्हूदड़ो\n2. तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल : धौलावीरा\n3. शैलकृत जल जलाशय व साइनबोर्ड : मोहनजोदड़ो\n4. कांस्य की नर्तकी : दक्षिण भारत (कर्नाटक-आंध्र)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: चन्हूदड़ो से लिपस्टिक, वक्राकार ईंटें व मनके बनाने के कारखाने मिले। (अन्य सही युग्म: तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल→आहार (राजस्थान), शैलकृत जल जलाशय व साइनबोर्ड→धौलावीरा, कांस्य की नर्तकी→मोहनजोदड़ो)।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु सभ्यता के साक्ष्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. शैलकृत जल जलाशय व साइनबोर्ड : मोहनजोदड़ो\n2. तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल : आहार (राजस्थान)\n3. कांस्य की नर्तकी : चन्हूदड़ो\n4. लिपस्टिक व बिना दुर्ग का औद्योगिक नगर : दक्षिण भारत (कर्नाटक-आंध्र)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: राजस्थान की बनास घाटी का आहार स्थल प्राचीन काल में 'तांबवती' कहलाता था। (अन्य सही युग्म: शैलकृत जल जलाशय व साइनबोर्ड→धौलावीरा, कांस्य की नर्तकी→मोहनजोदड़ो, लिपस्टिक व बिना दुर्ग का औद्योगिक नगर→चन्हूदड़ो)।"},
  {"q":"ऐतिहासिक संदर्भ में 'मुण्डकोपनिषद ('सत्यमेव जयते'), कठोपनिषद (यम-नचिकेता), बृहदारण्यक (याज्ञवल्क्य-गार्गी)' (प्रमुख ऐतिहासिक स्रोत) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","षड्दर्शन (छह भारतीय आस्तिक दर्शन)","प्रमुख उपनिषद एवं उनमें वर्णित प्रमुख संवाद","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)"],"correct":2,"explanation":"ऐतरेय ब्राह्मण में पुत्री को 'कृपण' कहा गया है, जबकि मैत्रायणी संहिता में मद्य व पासे के साथ स्त्री को तीन प्रमुख बुराइयों में गिना गया। जाबालोपनिषद में चारों आश्रम हैं।"},
  {"q":"ऐतिहासिक संदर्भ में 'नवपाषाण काल में हिरण के सींग व हड्डी के सर्वाधिक उपकरण' (प्रमुख ऐतिहासिक विशेषता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["बुर्जहोम (श्रीनगर, जम्मू-कश्मीर)","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","चिरांद (सारण, बिहार)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)"],"correct":2,"explanation":"बिहार के सारण जिले में स्थित चिरांद में नवपाषाण स्तरों से हिरण के सींगों से बने सैकड़ों हड्डी के औजार (सुई, बाणाग्र, छेनी) मिले हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक एवं आधुनिक नदियाँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सदानीरा : काबुल\n2. कुभा : झेलम\n3. शतुद्रि : सतलज\n4. वितस्ता : चिनाब","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: सतलज नदी का प्राचीन ऋग्वैदिक नाम 'शतुद्रि' था। (अन्य सही युग्म: सदानीरा→गंडक, कुभा→काबुल, वितस्ता→झेलम)।"},
  {"q":"ऐतिहासिक संदर्भ में 'भारत में प्रथम पुरापाषाण कालीन हैंड-एक्स (हस्त-कुठार) की खोज' (प्रमुख ऐतिहासिक विशेषता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["बुर्जहोम (श्रीनगर, जम्मू-कश्मीर)","पल्लवरम एवं अतिरमपक्कम (तमिलनाडु)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)"],"correct":1,"explanation":"भारतीय प्रागैतिहास के जनक कहे जाने वाले भूवैज्ञानिक रॉबर्ट ब्रूस फुट ने 1863 ई. में पल्लवरम से निम्न पुरापाषाण कालीन क्वार्टजाइट हस्त-कुठार खोजा।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मोहनजोदड़ो : प्रवरा नदी\n2. दैमाबाद : सतलज नदी\n3. आलमगीरपुर : हिंडन नदी\n4. रोपड़ : चिनाब नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: आलमगीरपुर उत्तर प्रदेश में हिंडन (यमुना की सहायक) नदी के तट पर स्थित था। (अन्य सही युग्म: मोहनजोदड़ो→सिन्धु नदी, दैमाबाद→प्रवरा नदी, रोपड़→सतलज नदी)।"},
  {"q":"'प्रमुख संगम ग्रंथ: पट्टुप्पाट्टु एवं एत्तुत्तोगै' के ऐतिहासिक संदर्भ में 'सौहार्द व ऐतिहासिक मूल्य' निम्नलिखित में से क्या है?","options":["'पट्टिनप्पालै' में कावेरीपट्टनम (पुहार) के व्यापार व करिकाल चोल का सजीव वर्णन मिलता है","नवपाषाण काल (लगभग 7000 ई.पू.), बोलन दर्रे के समीप","'तिरुकुरल' (तिरुवल्लुवर — तमिलों की बाइबिल), 'शिलप्पादिकारम्' (इलंगो आदिगल), 'मणिमेखलै' (सीतलै सतनार)","डॉ. वी.एस. वाकणकर (1957-58) द्वारा खोजा गया"],"correct":0,"explanation":"संगम काल में 'कोत्तवई' (विजय की देवी) की आराधना की जाती थी और उत्तर भारत के अगस्त्य ऋषि को तमिल संस्कृति के प्रसार से जोड़ा जाता है।"},
  {"q":"'संगमकालीन सामाजिक वर्ग, देवपूजा एवं कृषि शब्दावली' के ऐतिहासिक संदर्भ में 'प्रमुख देवता व पूजा' निम्नलिखित में से क्या है?","options":["नवपाषाण काल (लगभग 7000 ई.पू.), बोलन दर्रे के समीप","मुरुगन/सुब्रमण्यम (तमिलों के प्रमुख देवता), पत्तिनी पूजा (कण्णगी की सती-पूजा प्रथा)","डॉ. वी.एस. वाकणकर (1957-58) द्वारा खोजा गया","चोल करिकाल (पुहार/कावेरीपट्टनम व कावेरी बाँध); चेरा सेनगुट्टुवन; अरिकमेडु से रोमन बस्ती (एंफोरा)"],"correct":1,"explanation":"संगम काल में 'कावेरीपट्टनम' (पुहार) चोलों का प्रमुख बंदरगाह था जहाँ से मलमल व मसालों का अंतरराष्ट्रीय व्यापार होता था।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक एवं आधुनिक नदियाँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. कुभा : काबुल\n2. असिक्नी : गंडक\n3. सदानीरा : व्यास\n4. विपाशा : झेलम","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: अफगानिस्तान की काबुल नदी को ऋग्वेद में 'कुभा' कहा गया है। (अन्य सही युग्म: असिक्नी→चिनाब, सदानीरा→गंडक, विपाशा→व्यास)।"},
  {"q":"ऐतिहासिक संदर्भ में 'बौस्त्रोफेदन (भावचित्रात्मक) लिपि, सेलखड़ी मुहरें व 16 के गुणज में बाट' (प्रमुख तकनीकी विशेषता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["सैंधव स्थलों के क्षेत्रीय विस्तार (उत्तरी, दक्षिणी, पूर्वी, पश्चिमी सीमा)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","सिन्धु घाटी की लिपि, मुहरें एवं तौल प्रणाली"],"correct":3,"explanation":"सैंधव अर्थव्यवस्था विनिमय प्रणाली पर आधारित थी। मेसोपोटामिया के अभिलेखों में सिन्धु क्षेत्र के लिए 'मेलुहा' शब्द तथा कार्निलियन, लाजवर्द व टिन व्यापार का उल्लेख है।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. तिरुक्कुरल : विष्णु शर्मा\n2. पंचतंत्र : वराहमिहिर\n3. मणिमेखलै : सीतलै सतनार\n4. वृहत्संहिता : ब्रह्मगुप्त","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: मदुरै के धान व्यापारी कवि सीतलै सतनार ने 'मणिमेखलै' की रचना की। (अन्य सही युग्म: तिरुक्कुरल→तिरुवल्लुवर, पंचतंत्र→विष्णु शर्मा, वृहत्संहिता→वराहमिहिर)।"},
  {"q":"[PSC/CDS युग्म पहचान — षड्दर्शन एवं प्रवर्तक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. वैशेषिक दर्शन : महर्षि जैमिनी\n2. योग दर्शन : महर्षि पतंजलि\n3. पूर्व मीमांसा : महर्षि गौतम (अक्षपाद)\n4. न्याय दर्शन : महर्षि बादरायण (व्यास)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: पतंजलि ने 'योगसूत्र' में यम, नियम, आसन, प्राणायाम, प्रत्याहार, धारणा, ध्यान व समाधि का वर्णन किया। (अन्य सही युग्म: वैशेषिक दर्शन→महर्षि कणाद (उलूक), पूर्व मीमांसा→महर्षि जैमिनी, न्याय दर्शन→महर्षि गौतम (अक्षपाद))।"},
  {"q":"ऐतिहासिक संदर्भ में ''एत्तुत्तोगै' (8 संकलन: नट्टिणै, कुरुंदोगै, अहनानूरु, पुरनानूरु आदि) एवं 'पट्टुप्पाट्टु' (10 दीर्घ कविताएँ: तिरुमुरुगाट्टुप्पडै, पट्टिनप्पालै)' (संकलन वर्गीकरण) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["प्रमुख संगम ग्रंथ: पट्टुप्पाट्टु एवं एत्तुत्तोगै","तीन तमिल संगम एवं प्रमुख संगम साहित्य","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)"],"correct":0,"explanation":"संगम काल में 'कोत्तवई' (विजय की देवी) की आराधना की जाती थी और उत्तर भारत के अगस्त्य ऋषि को तमिल संस्कृति के प्रसार से जोड़ा जाता है।"},
  {"q":"संगमकालीन सामाजिक वर्ग, देवपूजा एवं कृषि शब्दावली — इसके संबंध में 'प्रमुख सामाजिक व कृषि पद' कौन/क्या था?","options":["पुरापाषाण से मध्यपाषाण काल के प्राचीनतम शैलचित्र","भारतीय उपमहाद्वीप में कृषि (गेहूँ-जौ) व पशुपालन के प्राचीनतम प्रमाण","चेर (धनुष-बाण, वंजि, बंदरगाह मुजिरिस); चोल (बाघ, उरैयूर/पुहार); पांड्य (मछली/कार्प, मदुरै, बंदरगाह कोरकई)","वेलालर (धनी कृषक), कड़ैसियर (कृषि मजदूर), अरसर (शासक वर्ग), एनादी (सेनापति की उपाधि)"],"correct":3,"explanation":"संगम काल में 'कावेरीपट्टनम' (पुहार) चोलों का प्रमुख बंदरगाह था जहाँ से मलमल व मसालों का अंतरराष्ट्रीय व्यापार होता था।"},
  {"q":"ऐतिहासिक संदर्भ में 'आहार/बनास (तांबवती, राजस्थान); मालवा (उत्कृष्ट मृदभांड, नवदाटोली); जोरवे (इनामगाँव व दैमाबाद, महाराष्ट्र); गणेश्वर (खेतड़ी ताँबा आपूर्ति)' (संस्कृति एवं स्थान) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मोहनजोदड़ो (लरकाना, सिन्ध)","ताम्रपाषाण संस्कृतियाँ: आहार, मालवा, जोरवे व गणेश्वर","हड़प्पा (मांटगोमरी/साहीवाल, पंजाब)","लोथल (अहमदाबाद, गुजरात)"],"correct":1,"explanation":"मालवा ताम्रपाषाण मृदभांड (काला-लाल व चित्रित लाल-काले बर्तन) अपनी उत्कृष्ट बनावट के लिए सभी ताम्रपाषाण संस्कृतियों में सर्वश्रेष्ठ माने जाते हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. संगम ग्रंथ 'एत्तुत्तोगै' केवल वैदिक कर्मकांड और हवन विधियों के संस्कृत मंत्रों का अनुवाद मात्र है।\n2. कुषाण शासक कनिष्क के काल में चतुर्थ संगीति में बुद्ध की मूर्ति पूजा व बोधिसत्त्व आदर्श वाली महायान शाखा पृथक हुई।\n3. बौद्ध दर्शन ईश्वर और शाश्वत आत्मा की सत्ता को नकारता है (अनात्मवाद), किंतु पुनर्जन्म और कर्म के नियम को स्वीकार करता है।\n4. भद्रबाहु (जो चंद्रगुप्त मौर्य के साथ श्रवणबेलगोला गए) के अनुयायी 'दिगम्बर' कहलाए, जबकि पाटलिपुत्र में रहे स्थूलभद्र के अनुयायी 'श्वेताम्बर' कहलाए।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'एत्तुत्तोगै' विशुद्ध तमिल काव्य संकलन है जो प्राचीन दक्षिण भारतीय समाज, प्रेम, युद्ध और व्यापार का प्राथमिक ऐतिहासिक स्रोत है।"},
  {"q":"प्रमुख संगम ग्रंथ: पट्टुप्पाट्टु एवं एत्तुत्तोगै — इसके संबंध में 'संकलन वर्गीकरण' कौन/क्या था?","options":["ये तीनों प्रारंभिक स्थविरवाद/हीनयान परंपरा के उप-संप्रदाय थे (UPSC PYQ)","पुरापाषाण से मध्यपाषाण काल के प्राचीनतम शैलचित्र","'एत्तुत्तोगै' (8 संकलन: नट्टिणै, कुरुंदोगै, अहनानूरु, पुरनानूरु आदि) एवं 'पट्टुप्पाट्टु' (10 दीर्घ कविताएँ: तिरुमुरुगाट्टुप्पडै, पट्टिनप्पालै)","पांड्य राजाओं के संरक्षण में मदुरै व कपाटपुरम में 3 संगम; 'तोलकाप्पियम्' (तमिल व्याकरण, द्वितीय संगम की एकमात्र उपलब्ध कृति)"],"correct":2,"explanation":"संगम काल में 'कोत्तवई' (विजय की देवी) की आराधना की जाती थी और उत्तर भारत के अगस्त्य ऋषि को तमिल संस्कृति के प्रसार से जोड़ा जाता है।"},
  {"q":"ऐतिहासिक संदर्भ में 'दुर्गरहित (Without Citadel) औद्योगिक नगर, लिपस्टिक व मनके बनाने का कारखाना' (प्रमुख पुरातात्विक साक्ष्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["हड़प्पा (मांटगोमरी/साहीवाल, पंजाब)","लोथल (अहमदाबाद, गुजरात)","मोहनजोदड़ो (लरकाना, सिन्ध)","चन्हूदड़ो (सिन्ध प्रांत, पाकिस्तान)"],"correct":3,"explanation":"सिन्धु नदी के तट पर चन्हूदड़ो की खोज एन.जी. मजूमदार (1931) और उत्खनन अर्नेस्ट मैके ने किया। यहाँ वक्राकार ईंटें व बिल्ली का पीछा करते कुत्ते के पंजों के निशान मिले।"},
  {"q":"ऐतिहासिक संदर्भ में 'भारतीय उपमहाद्वीप में कृषि (गेहूँ-जौ) व पशुपालन के प्राचीनतम प्रमाण' (प्रमुख ऐतिहासिक विशेषता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","कोल्डिहवा एवं लहुरादेव (उत्तर प्रदेश)","बुर्जहोम (श्रीनगर, जम्मू-कश्मीर)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)"],"correct":0,"explanation":"पाकिस्तान के बलूचिस्तान में बोलन दर्रे के निकट स्थित मेहरगढ़ नवपाषाण काल में गेहूँ, जौ और कपास की खेती के प्रारंभिक प्रमाणों के लिए विख्यात है।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. दैमाबाद : प्रवरा नदी\n2. आलमगीरपुर : सतलज नदी\n3. रोपड़ : रावी नदी\n4. हड़प्पा : सिन्धु नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: दैमाबाद महाराष्ट्र में गोदावरी की सहायक प्रवरा नदी के तट पर स्थित था। (अन्य सही युग्म: आलमगीरपुर→हिंडन नदी, रोपड़→सतलज नदी, हड़प्पा→रावी नदी)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: संगम साहित्य को भावना के आधार पर 'अहम्' (प्रेम संबंधी) और 'पुरम्' (युद्ध व वीरता संबंधी) दो मुख्य श्रेणियों में बाँटा गया है।\nकथन-2: महाजनपद एवं राजधानियाँ के अंतर्गत 'शूरसेन महाजनपद' का ऐतिहासिक संबंध 'तक्षशिला' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (संगम साहित्य को भावना के आधार पर 'अहम्' (प्रेम संबंधी) और 'पुरम्' (युद्ध व वीरता संबंधी) दो मुख्य श्रेणियों में बाँटा गया है।)। कथन-2 गलत है — 'शूरसेन महाजनपद' का सही संबंध 'मथुरा' से था — शूरसेन महाजनपद की राजधानी मथुरा थी जहाँ अवंतिपुत्र शासक बुद्ध अनुयायी था।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लोथल : भोगवा नदी\n2. मोहनजोदड़ो : सतलज नदी\n3. रोपड़ : रावी नदी\n4. हड़प्पा : घग्घर नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: लोथल गुजरात में भोगवा नदी के तट पर स्थित सैंधव बंदरगाह था। (अन्य सही युग्म: मोहनजोदड़ो→सिन्धु नदी, रोपड़→सतलज नदी, हड़प्पा→रावी नदी)।"},
  {"q":"[PSC/CDS युग्म पहचान — षड्दर्शन एवं प्रवर्तक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सांख्य दर्शन : महर्षि पतंजलि\n2. योग दर्शन : महर्षि कणाद (उलूक)\n3. पूर्व मीमांसा : महर्षि जैमिनी\n4. वैशेषिक दर्शन : महर्षि बादरायण (व्यास)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: महर्षि जैमिनी ने वैदिक यज्ञ व अपूर्व सिद्धांत पर पूर्व मीमांसा की स्थापना की। (अन्य सही युग्म: सांख्य दर्शन→महर्षि कपिल, योग दर्शन→महर्षि पतंजलि, वैशेषिक दर्शन→महर्षि कणाद (उलूक))।"},
  {"q":"ऐतिहासिक संदर्भ में 'सांख्य (कपिल), योग (पतंजलि), न्याय (गौतम), वैशेषिक (कणाद), पूर्वमीमांसा (जैमिनी), उत्तरमीमांसा (बादरायण)' (दर्शन एवं प्रवर्तक) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","षड्दर्शन (छह भारतीय आस्तिक दर्शन)","प्रमुख उपनिषद एवं उनमें वर्णित प्रमुख संवाद","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)"],"correct":1,"explanation":"महर्षि कणाद का वैशेषिक दर्शन भौतिक विज्ञान और परमाणु सिद्धांत की नींव रखता है। महर्षि गौतम का न्याय दर्शन तर्कशास्त्र (प्रमाण मीमांसा) पर केंद्रित है।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. परिशिष्टपर्वन् : हेमचंद्र (कलिकाल सर्वज्ञ)\n2. किरातार्जुनीयम् : महेंद्रवर्मन प्रथम\n3. मत्तविलासप्रहसन : अमरसिंह\n4. अमरकोश : कल्हण","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: गुजरात के सोलंकी शासक कुमारपाल के गुरु आचार्य हेमचंद्र ने 'परिशिष्टपर्वन्' लिखा। (अन्य सही युग्म: किरातार्जुनीयम्→भारवि, मत्तविलासप्रहसन→महेंद्रवर्मन प्रथम, अमरकोश→अमरसिंह)।"},
  {"q":"ऐतिहासिक संदर्भ में 'भास ('स्वप्नवासवदत्तम्'); कालिदास ('अभिज्ञानशाकुन्तलम्', 'मेघदूत'); विशाखदत्त ('मुद्राराक्षस', 'देवीचंद्रगुप्तम्')' (प्रमुख रचना एवं लेखक) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["विदेशी प्राचीन यात्रियों व लेखकों के प्रमुख विवरण","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","प्राचीन संस्कृत नाटक एवं ऐतिहासिक महाकाव्य"],"correct":3,"explanation":"जयदेव कृत 'गीतगोविंद', बिल्हण की 'विक्रमांकदेवचरित', संध्याकर नंदी की 'रामचरित' (कैवर्त विद्रोह) और हेमचंद्र की 'परिशिष्टपर्वन्' प्रमुख ऐतिहासिक कृतियाँ हैं।"},
  {"q":"ऐतिहासिक संदर्भ में 'विशाल स्नानागार, कांस्य की नर्तकी, पशुपति मुहर व सूती कपड़ा' (प्रमुख पुरातात्विक साक्ष्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["लोथल (अहमदाबाद, गुजरात)","कालीबंगा (हनुमानगढ़, राजस्थान)","मोहनजोदड़ो (लरकाना, सिन्ध)","हड़प्पा (मांटगोमरी/साहीवाल, पंजाब)"],"correct":2,"explanation":"सिन्धु नदी के दाएँ तट पर स्थित मोहनजोदड़ो की खोज 1922 में राखालदास बनर्जी ने की। यहाँ से महाविद्यालय भवन, सभागार और दाढ़ी वाले योगी की मूर्ति मिली।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. शिलप्पादिकारम् : पालकाप्य\n2. हस्त्यायुर्वेद : पतंजलि\n3. महाभाष्य : पाणिनि\n4. तिरुक्कुरल : तिरुवल्लुवर","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: महान तमिल संत कवि तिरुवल्लुवर ने 'तिरुक्कुरल' (1330 कुरल) की रचना की। (अन्य सही युग्म: शिलप्पादिकारम्→इलंगो आदिगल, हस्त्यायुर्वेद→पालकाप्य, महाभाष्य→पतंजलि)।"},
  {"q":"ऐतिहासिक संदर्भ में 'पक्की ईंटों का कृत्रिम गोदीबाड़ा (Dockyard), युगल शवाधान व फारस की मुहर' (प्रमुख पुरातात्विक साक्ष्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["हड़प्पा (मांटगोमरी/साहीवाल, पंजाब)","लोथल (अहमदाबाद, गुजरात)","मोहनजोदड़ो (लरकाना, सिन्ध)","कालीबंगा (हनुमानगढ़, राजस्थान)"],"correct":1,"explanation":"भोगवा नदी किनारे स्थित लोथल की खोज एस.आर. राव ने की। यहाँ से चावल के दाने, अग्निवेदिकाएँ, मनके बनाने का कारखाना और हाथीदाँत का पैमाना मिला।"},
  {"q":"'संगमकालीन चेर, चोल एवं पांड्य राज्य तथा प्रमुख बंदरगाह' के ऐतिहासिक संदर्भ में 'प्रमुख शासक व रोम व्यापार' निम्नलिखित में से क्या है?","options":["मुरुगन/सुब्रमण्यम (तमिलों के प्रमुख देवता), पत्तिनी पूजा (कण्णगी की सती-पूजा प्रथा)","डॉ. वी.एस. वाकणकर (1957-58) द्वारा खोजा गया","चोल करिकाल (पुहार/कावेरीपट्टनम व कावेरी बाँध); चेरा सेनगुट्टुवन; अरिकमेडु से रोमन बस्ती (एंफोरा)","नवपाषाण काल (लगभग 7000 ई.पू.), बोलन दर्रे के समीप"],"correct":2,"explanation":"अनाम नाविक की पुस्तक 'पेरिप्लस ऑफ द एरिथ्रियन सी' तथा प्लिनी के विवरण में रोम से भारत की ओर स्वर्ण के भारी प्रवाह पर चिंता जताई गई है।"},
  {"q":"तीन तमिल संगम एवं प्रमुख संगम साहित्य — इसके संबंध में 'संगम सम्मेलन' कौन/क्या था?","options":["भारतीय उपमहाद्वीप में कृषि (गेहूँ-जौ) व पशुपालन के प्राचीनतम प्रमाण","पांड्य राजाओं के संरक्षण में मदुरै व कपाटपुरम में 3 संगम; 'तोलकाप्पियम्' (तमिल व्याकरण, द्वितीय संगम की एकमात्र उपलब्ध कृति)","पुरापाषाण से मध्यपाषाण काल के प्राचीनतम शैलचित्र","'एत्तुत्तोगै' (8 संकलन: नट्टिणै, कुरुंदोगै, अहनानूरु, पुरनानूरु आदि) एवं 'पट्टुप्पाट्टु' (10 दीर्घ कविताएँ: तिरुमुरुगाट्टुप्पडै, पट्टिनप्पालै)"],"correct":1,"explanation":"संगम काल में तिनै (पाँच भौगोलिक क्षेत्र): कुरिंजी (पहाड़), मुल्लै (चरागाह), मरुतम (उपजाऊ मैदान), नेथल (तटीय) और पालै (शुष्क) वर्णित हैं।"},
  {"q":"ऐतिहासिक संदर्भ में '10 मंडल व 1028 सूक्त; तृतीय मंडल में गायत्री मंत्र (विश्वामित्र)' (संरचना एवं विषयवस्तु) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["वेदांग, सूत्र साहित्य एवं संस्कार","सामवेद, यजुर्वेद एवं अथर्ववेद","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","ऋग्वेद एवं इसके प्रमुख मंडल"],"correct":3,"explanation":"ऋग्वेद की भाषा प्राक्-संस्कृत है। इसके पुरोहित को 'होता' या 'होतृ' कहा जाता था। सातवें मंडल में सुदास और दस राजाओं के मध्य रावी (परुष्णी) तट पर हुए दाशराज्ञ युद्ध का वर्णन है।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मृच्छकटिकम् : विशाखदत्त\n2. हस्त्यायुर्वेद : पालकाप्य\n3. मुद्राराक्षस : तिरुवल्लुवर\n4. तिरुक्कुरल : दण्डी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: गुप्तकालीन पशुचिकित्सक पालकाप्य ने हाथियों के रोगों व उपचार पर 'हस्त्यायुर्वेद' लिखा। (अन्य सही युग्म: मृच्छकटिकम्→शूद्रक, मुद्राराक्षस→विशाखदत्त, तिरुक्कुरल→तिरुवल्लुवर)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मुद्राराक्षस : विशाखदत्त\n2. परिशिष्टपर्वन् : विष्णु शर्मा\n3. पंचतंत्र : पाणिनि\n4. अष्टाध्यायी : सीतलै सतनार","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: गुप्तकालीन नाटककार विशाखदत्त ने 'मुद्राराक्षस' तथा 'देवीचंद्रगुप्तम्' की रचना की। (अन्य सही युग्म: परिशिष्टपर्वन्→हेमचंद्र (कलिकाल सर्वज्ञ), पंचतंत्र→विष्णु शर्मा, अष्टाध्यायी→पाणिनि)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मत्तविलासप्रहसन : वराहमिहिर\n2. वृहत्संहिता : गुप्तकाल (बोवर पांडुलिपि)\n3. नवनीतकम (आयुर्वेद ग्रंथ) : विष्णु शर्मा\n4. महाभाष्य : पतंजलि","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: पुष्यमित्र शुंग के समकालीन पतंजलि ने 'महाभाष्य' एवं 'योगसूत्र' की रचना की। (अन्य सही युग्म: मत्तविलासप्रहसन→महेंद्रवर्मन प्रथम, वृहत्संहिता→वराहमिहिर, नवनीतकम (आयुर्वेद ग्रंथ)→गुप्तकाल (बोवर पांडुलिपि))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. प्रसिद्ध तमिल महाकाव्य 'शिलप्पादिकारम्' (कोवलन व कण्णगी की कथा) की रचना मणिवण्णन नामक चोल सम्राट द्वारा 12वीं सदी में की गई।\n2. शूद्र/अक्षत्रिय कुल से उत्पन्न महापद्मनंद को पुराणों में 'सर्वक्षत्रान्तक' और 'द्वितीय परशुराम' कहा गया है; उसने कलिंग पर विजय प्राप्त की।\n3. ऋग्वेद में आधुनिक झेलम नदी को 'वितस्ता' कहा गया है।\n4. देवगढ़ का दशावतार मंदिर विष्णु के अनंतशायी व गजेंद्रमोक्ष शिल्पों के लिए प्रसिद्ध है।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'शिलप्पादिकारम्' की रचना चेर शासक सेनगुट्टुवन के भाई इलंगो आदिगल ने संगम काल में की थी जिसमें कण्णगी (पत्नी पूजा) का वर्णन है।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अहं ब्रह्मास्मि : तैत्तिरीय उपनिषद\n2. संगृहीता : कोषाध्यक्ष\n3. अतिथि देवो भव : गायों के लिए युद्ध / खोज\n4. गविष्टि : गेहूँ","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: उत्तर-वैदिक काल में 'संगृहीता' शाही कोषाध्यक्ष होता था। (अन्य सही युग्म: अहं ब्रह्मास्मि→बृहदारण्यक उपनिषद, अतिथि देवो भव→तैत्तिरीय उपनिषद, गविष्टि→गायों के लिए युद्ध / खोज)।"},
  {"q":"ऐतिहासिक संदर्भ में 'सामवेद (भारतीय संगीत जनक), यजुर्वेद (यज्ञ विधियाँ-गद्य/पद्य), अथर्ववेद (औषधि/तंत्र-मंत्र)' (प्रमुख विषयवस्तु) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["ऋग्वेद एवं इसके प्रमुख मंडल","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","सामवेद, यजुर्वेद एवं अथर्ववेद","वेदांग, सूत्र साहित्य एवं संस्कार"],"correct":2,"explanation":"इन तीनों वेदों के पुरोहित क्रमशः उद्गाता (सामवेद), अध्वर्यु (यजुर्वेद) और ब्रह्मा (अथर्ववेद) थे। प्रथम तीन वेदों को 'वेदत्रयी' कहा जाता है।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक एवं आधुनिक नदियाँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. परुष्णी : सतलज\n2. विपाशा : व्यास\n3. शतुद्रि : काबुल\n4. कुभा : गंडक","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: ऋग्वेद में वर्तमान व्यास नदी को 'विपाशा' कहा गया है। (अन्य सही युग्म: परुष्णी→रावी, शतुद्रि→सतलज, कुभा→काबुल)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अष्टाध्यायी : पालकाप्य\n2. हस्त्यायुर्वेद : विशाखदत्त\n3. किरातार्जुनीयम् : भारवि\n4. मुद्राराक्षस : विष्णु शर्मा","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: पल्लव राजदरबार से जुड़े भारवि ने 'किरातार्जुनीयम्' महाकाव्य की रचना की। (अन्य सही युग्म: अष्टाध्यायी→पाणिनि, हस्त्यायुर्वेद→पालकाप्य, मुद्राराक्षस→विशाखदत्त)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. काशी के राजा अश्वसेन के पुत्र पार्श्वनाथ ने झारखंड के सम्मेद शिखर (पार्श्वनाथ पहाड़ी) पर निर्वाण पाया।\n2. चीनी यात्री ह्वेनसांग ने हर्ष के काल में भारत भ्रमण किया और बताया कि समाज में अस्पृश्यता विद्यमान थी, सूती/कौशेय वस्त्र प्रमुख थे और राजकोष 4 भागों में बँटता था।\n3. संगम काल के मुरुगन देवता की उपासना वैदिक आर्यों के इंद्र देव से पूर्णतः भिन्न केवल उत्तरी पंजाब तक सीमित थी।\n4. महावीर स्वामी का जन्म ज्ञातृक कुल में हुआ था; उनके प्रथम शिष्य एवं दामाद जामालि थे। पार्श्वनाथ के 4 महाव्रतों में महावीर ने 5वाँ 'ब्रह्मचर्य' जोड़ा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: मुरुगन (दक्षिण में स्कंद/कार्तिकेय के समरूप) तमिल प्रदेश (विशेषतः पहाड़ी कुरिंजी क्षेत्र) के सर्वाधिक लोकप्रिय देवता थे।"},
  {"q":"ऐतिहासिक संदर्भ में 'बोगजकोई (1400 ई.पू. — इंद्र, मित्र, वरुण, नासत्य); नानेघाट (नागनिका); मंदसौर (कुमारगुप्त/यशोधर्मन); भीतरी (स्कंदगुप्त); एरण (भानुगुप्त)' (अभिलेख एवं शासक) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","बुर्जहोम (श्रीनगर, जम्मू-कश्मीर)","प्राचीन भारत के ऐतिहासिक महत्व वाले प्रमुख अभिलेख"],"correct":3,"explanation":"उत्तरमेरूर अभिलेख (चोल परांतक I) ग्राम प्रशासन की लोकतांत्रिक कुडवोलाई प्रणाली तथा सोहगौरा-महास्थान (मौर्यकाल) अकाल के समय अनाज वितरण का प्रमाण देते हैं।"},
  {"q":"ऐतिहासिक संदर्भ में 'जुते हुए खेत के साक्ष्य, अलंकृत ईंटें, सात अग्निवेदिकाएँ व भूकंप प्रमाण' (प्रमुख पुरातात्विक साक्ष्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["लोथल (अहमदाबाद, गुजरात)","मोहनजोदड़ो (लरकाना, सिन्ध)","हड़प्पा (मांटगोमरी/साहीवाल, पंजाब)","कालीबंगा (हनुमानगढ़, राजस्थान)"],"correct":3,"explanation":"घग्घर नदी किनारे कालीबंगा (अर्थ: काले रंग की चूड़ियाँ) की खोज 1953 में अमलानंद घोष ने की। यहाँ से ऊँट की हड्डियाँ और शल्यक्रिया (खोपड़ी में छेद) के साक्ष्य मिले।"},
  {"q":"ऐतिहासिक संदर्भ में 'चेर (धनुष-बाण, वंजि, बंदरगाह मुजिरिस); चोल (बाघ, उरैयूर/पुहार); पांड्य (मछली/कार्प, मदुरै, बंदरगाह कोरकई)' (राजचिह्न एवं राजधानियाँ) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["संगमकालीन सामाजिक वर्ग, देवपूजा एवं कृषि शब्दावली","संगमकालीन चेर, चोल एवं पांड्य राज्य तथा प्रमुख बंदरगाह","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)"],"correct":1,"explanation":"अनाम नाविक की पुस्तक 'पेरिप्लस ऑफ द एरिथ्रियन सी' तथा प्लिनी के विवरण में रोम से भारत की ओर स्वर्ण के भारी प्रवाह पर चिंता जताई गई है।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक एवं आधुनिक नदियाँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. विपाशा : झेलम\n2. वितस्ता : चिनाब\n3. असिक्नी : रावी\n4. सदानीरा : गंडक","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: बिहार की गंडक नदी को वैदिक साहित्य में 'सदानीरा' कहा गया है। (अन्य सही युग्म: विपाशा→व्यास, वितस्ता→झेलम, असिक्नी→चिनाब)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अमरकोश : भारवि\n2. पंचतंत्र : विष्णु शर्मा\n3. किरातार्जुनीयम् : तिरुवल्लुवर\n4. तिरुक्कुरल : बिल्हण","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: विष्णु शर्मा ने राजकुमारों को व्यावहारिक नीति व कूटनीति सिखाने हेतु 'पंचतंत्र' लिखा। (अन्य सही युग्म: अमरकोश→अमरसिंह, किरातार्जुनीयम्→भारवि, तिरुक्कुरल→तिरुवल्लुवर)।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. गोधूम : मुद्रा/मूल्य की इकाइयाँ\n2. अतिथि देवो भव : तैत्तिरीय उपनिषद\n3. निष्क व शतमन : छान्दोग्य उपनिषद\n4. तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु) : बृहदारण्यक उपनिषद","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: तैत्तिरीय उपनिषद में गुरु द्वारा शिष्य को दीक्षांत उपदेश में 'अतिथि देवो भव' कहा गया है। (अन्य सही युग्म: गोधूम→गेहूँ, निष्क व शतमन→मुद्रा/मूल्य की इकाइयाँ, तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु)→छान्दोग्य उपनिषद)।"},
  {"q":"ऐतिहासिक संदर्भ में 'मेगस्थनीज ('इण्डिका'); टॉलमी ('जियोग्राफी'); प्लिनी ('नेचुरल हिस्टोरिका'); फाह्यान ('फो-क्यू-की'); ह्वेनसांग ('सी-यू-की'); इत्सिंग' (यात्री एवं प्रमुख रचना) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["प्राचीन संस्कृत नाटक एवं ऐतिहासिक महाकाव्य","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","विदेशी प्राचीन यात्रियों व लेखकों के प्रमुख विवरण","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)"],"correct":2,"explanation":"अल-मसूदी (राष्ट्रकूट-प्रतिहार काल) तथा इब्न खुर्दादबा ने भी प्रारंभिक मध्ययुगीन भारत की राजनीतिक व व्यापारिक दशा पर प्रकाश डाला।"},
  {"q":"ऐतिहासिक संदर्भ में 'भागदुघ (कर संग्रहकर्ता), संगृहीता (कोषाध्यक्ष), अक्षवाप (पासे खेल का अधिकारी/लेखाकार)' (प्रमुख पदाधिकारी) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["उत्तर-वैदिक काल के रत्निन एवं कर अधिकारी","महाकाव्य, स्मृतियाँ एवं पुराण साहित्य","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","ऋग्वैदिक प्रशासनिक एवं सामाजिक शब्दावली"],"correct":0,"explanation":"शतपथ ब्राह्मण में विदेह माधव की कथा द्वारा गंडक (सदानीरा) के पूर्व तक आर्यों के विस्तार तथा कृषि संबंधी चार क्रियाओं (जुताई, बुवाई, कटाई, मड़ाई) का वर्णन है।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु सभ्यता के साक्ष्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल : धौलावीरा\n2. शैलकृत जल जलाशय व साइनबोर्ड : चन्हूदड़ो\n3. कांस्य की नर्तकी : मोहनजोदड़ो\n4. लिपस्टिक व बिना दुर्ग का औद्योगिक नगर : दक्षिण भारत (कर्नाटक-आंध्र)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: मोहनजोदड़ो से लॉस्ट-वैक्स (मोम-साँचा) तकनीक से निर्मित कांस्य की नर्तकी मिली। (अन्य सही युग्म: तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल→आहार (राजस्थान), शैलकृत जल जलाशय व साइनबोर्ड→धौलावीरा, लिपस्टिक व बिना दुर्ग का औद्योगिक नगर→चन्हूदड़ो)।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. रंगपुर : सतलज नदी\n2. सुत्कागेंडोर : दाश्क नदी\n3. रोपड़ : चिनाब नदी\n4. मांडा : रावी नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: सुत्कागेंडोर बलूचिस्तान में दाश्क नदी के किनारे स्थित सैंधव सभ्यता का सबसे पश्चिमी छोर था। (अन्य सही युग्म: रंगपुर→मादर/भादर नदी, रोपड़→सतलज नदी, मांडा→चिनाब नदी)।"},
  {"q":"ऐतिहासिक संदर्भ में 'मिट्टी का बना हल (खिलौना), उत्तम किस्म के जौ व तारांकित/अरीय सड़कें' (प्रमुख पुरातात्विक साक्ष्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["बनावली (फतेहाबाद, हरियाणा)","मोहनजोदड़ो (लरकाना, सिन्ध)","लोथल (अहमदाबाद, गुजरात)","हड़प्पा (मांटगोमरी/साहीवाल, पंजाब)"],"correct":0,"explanation":"हरियाणा के बनावली का उत्खनन 1974 में आर.एस. बिष्ट ने किया। यहाँ से लाजवर्द मणि, ताँबे के बाणाग्र और अच्छी किस्म का जौ प्राप्त हुआ।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु सभ्यता के साक्ष्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल : मोहनजोदड़ो\n2. कांस्य की नर्तकी : चन्हूदड़ो\n3. लिपस्टिक व बिना दुर्ग का औद्योगिक नगर : दक्षिण भारत (कर्नाटक-आंध्र)\n4. शैलकृत जल जलाशय व साइनबोर्ड : धौलावीरा","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: धौलावीरा से उत्कृष्ट पत्थर के बने विशाल जलाशय व 10 अक्षरों का साइनबोर्ड मिला। (अन्य सही युग्म: तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल→आहार (राजस्थान), कांस्य की नर्तकी→मोहनजोदड़ो, लिपस्टिक व बिना दुर्ग का औद्योगिक नगर→चन्हूदड़ो)।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. दैमाबाद : हिंडन नदी\n2. कालीबंगा : घग्घर नदी\n3. आलमगीरपुर : भोगवा नदी\n4. लोथल : चिनाब नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: कालीबंगा राजस्थान में प्राचीन घग्घर नदी के तट पर स्थित था। (अन्य सही युग्म: दैमाबाद→प्रवरा नदी, आलमगीरपुर→हिंडन नदी, लोथल→भोगवा नदी)।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लोथल : घग्घर नदी\n2. कालीबंगा : दाश्क नदी\n3. सुत्कागेंडोर : प्रवरा नदी\n4. मोहनजोदड़ो : सिन्धु नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: मोहनजोदड़ो सिन्धु नदी के दाएँ तट पर स्थित था। (अन्य सही युग्म: लोथल→भोगवा नदी, कालीबंगा→घग्घर नदी, सुत्कागेंडोर→दाश्क नदी)।"},
  {"q":"[PSC/CDS युग्म पहचान — षड्दर्शन एवं प्रवर्तक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. योग दर्शन : महर्षि कणाद (उलूक)\n2. वैशेषिक दर्शन : महर्षि बादरायण (व्यास)\n3. सांख्य दर्शन : महर्षि कपिल\n4. उत्तर मीमांसा (वेदांत) : महर्षि जैमिनी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: महर्षि कपिल प्रणीत सांख्य दर्शन प्रकृति और पुरुष के द्वैत पर आधारित है। (अन्य सही युग्म: योग दर्शन→महर्षि पतंजलि, वैशेषिक दर्शन→महर्षि कणाद (उलूक), उत्तर मीमांसा (वेदांत)→महर्षि बादरायण (व्यास))।"},
  {"q":"ऐतिहासिक संदर्भ में 'बराबर/नागार्जुनी (अशोक व दशरथ — आजीवक); उदयगिरि-खंडगिरि (खारवेल — जैन); कार्ले/भाजा/कन्हेरी (सातवाहन — हीनयान बौद्ध चैत्य)' (गुफा समूह एवं आश्रयदाता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["प्राचीन गुफा स्थापत्य: बराबर, उदयगिरि, कार्ले एवं कन्हेरी","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","गांधार, मथुरा एवं अमरावती मूर्तिकला शैलियों की तुलना"],"correct":0,"explanation":"मध्य प्रदेश में विदिशा के समीप उदयगिरि की गुफाएँ गुप्तकाल (चंद्रगुप्त II) से संबंधित हैं जिनमें विष्णु के वराह अवतार की प्रसिद्ध मूर्ति है।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. चिरांद दक्षिण भारत में केवल कांस्य मूर्तियों और जहाजी गोदीबाड़ा के लिए जाना जाता है।\n2. पांड्य राज्य का बंदरगाह 'कोरकई' मोतियों के लिए तथा चेर राज्य का 'मुजिरिस' रोमन व्यापार (यवनप्रिय काली मिर्च) के लिए विश्वप्रसिद्ध था।\n3. प्राचीन ग्रंथ एवं रचयिता के अंतर्गत 'परिशिष्टपर्वन्' का ऐतिहासिक संबंध 'विष्णु शर्मा' से था।\n4. षड्दर्शन एवं प्रवर्तक के अंतर्गत 'सांख्य दर्शन' का ऐतिहासिक संबंध 'महर्षि कणाद (उलूक)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (पांड्य राज्य का बंदरगाह 'कोरकई' मोतियों के लिए तथा चेर राज्य का 'मुजिरिस' रोमन व्यापार (यवनप्रिय काली मिर्च) के लिए विश्वप्रसिद्ध था।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"ऐतिहासिक संदर्भ में 'पांड्य राजाओं के संरक्षण में मदुरै व कपाटपुरम में 3 संगम; 'तोलकाप्पियम्' (तमिल व्याकरण, द्वितीय संगम की एकमात्र उपलब्ध कृति)' (संगम सम्मेलन) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["प्रमुख संगम ग्रंथ: पट्टुप्पाट्टु एवं एत्तुत्तोगै","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","तीन तमिल संगम एवं प्रमुख संगम साहित्य","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)"],"correct":2,"explanation":"संगम काल में तिनै (पाँच भौगोलिक क्षेत्र): कुरिंजी (पहाड़), मुल्लै (चरागाह), मरुतम (उपजाऊ मैदान), नेथल (तटीय) और पालै (शुष्क) वर्णित हैं।"},
  {"q":"ऐतिहासिक संदर्भ में 'नागर (उत्तरापथ: रेखीय शिखर, आमलक-कलश, बिना चारदीवारी); द्रविड़ (दक्षिण: पिरामिड विमान, गोपुरम प्रवेशद्वार, चारदीवारी-जलकुंड); बेसर (मिश्रित)' (मुख्य स्थापत्य लक्षण) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["सोलंकी (मारु-गुर्जर) व होयसल (वेसर) मंदिर वास्तुकला","ओडिशा की कलिंग मंदिर शैली: लिंगराज, कोणार्क सूर्य व जगन्नाथ","खजुराहो के चंदेल मंदिर व कंदरिया महादेव मंदिर","प्राचीन मंदिर शैलियाँ: नागर, द्रविड़ एवं बेसर"],"correct":3,"explanation":"देवगढ़ (ललितपुर, उ.प्र.) का गुप्तकालीन दशावतार मंदिर उत्तर भारत में 'शिखर' तथा 'पंचायतन शैली' के प्राचीनतम उदाहरणों में से एक है।"},
  {"q":"ऐतिहासिक संदर्भ में 'पुरापाषाण से मध्यपाषाण काल के प्राचीनतम शैलचित्र' (प्रमुख ऐतिहासिक विशेषता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","बुर्जहोम (श्रीनगर, जम्मू-कश्मीर)","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","कोल्डिहवा एवं लहुरादेव (उत्तर प्रदेश)"],"correct":0,"explanation":"मध्य प्रदेश के रायसेन जिले में विंध्य पर्वतमाला में स्थित भीमबेटका की खोज 1957-58 में वी.एस. वाकणकर ने की थी। इसे 2003 में यूनेस्को विश्व धरोहर घोषित किया गया।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. नवनीतकम (आयुर्वेद ग्रंथ) : गुप्तकाल (बोवर पांडुलिपि)\n2. राजतरंगिणी : हेमचंद्र (कलिकाल सर्वज्ञ)\n3. परिशिष्टपर्वन् : दण्डी\n4. दशकुमारचरितम् : भास","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: गुप्तकाल में रचित 'नवनीतकम' आयुर्वेदिक नुस्खों, चूर्ण व काढ़े का प्राचीन संकलन है। (अन्य सही युग्म: राजतरंगिणी→कल्हण, परिशिष्टपर्वन्→हेमचंद्र (कलिकाल सर्वज्ञ), दशकुमारचरितम्→दण्डी)।"},
  {"q":"[UPSC Prelims PYQ] प्राचीन दक्षिण भारत के 'संगम साहित्य' के संदर्भ में निम्नलिखित कथनों में से कौन-सा एक सही है?","options":["इनका संकलन गुप्त काल के बाद गुजरात में हुआ","संगम कविताओं में समाज के किसी भी वर्ग की निर्धनता का उल्लेख नहीं है","संगम कविताओं में भौतिक संस्कृति का सजीव वर्णन है तथा वर्ण-व्यवस्था का उत्तर भारत जैसा कठोर रूप प्रारंभिक स्तर पर नहीं था","संगम ग्रंथों की भाषा प्राचीन संस्कृत थी"],"correct":2,"explanation":"UPSC CSE 2022: संगम साहित्य (तमिल भाषा) में न केवल राजाओं बल्कि सामान्य लोगों, योद्धाओं, किसानों व निर्धनों के सामाजिक जीवन और 'पुनाम्-तिएइ' भौगोलिक क्षेत्रों का सजीव वर्णन है।"},
  {"q":"ऐतिहासिक संदर्भ में 'गर्तावास (गड्ढे वाले घर) एवं मालिक के साथ कुत्ते दफनाने के साक्ष्य' (प्रमुख ऐतिहासिक विशेषता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","कोल्डिहवा एवं लहुरादेव (उत्तर प्रदेश)","बुर्जहोम (श्रीनगर, जम्मू-कश्मीर)"],"correct":3,"explanation":"कश्मीर घाटी के बुर्जहोम नवपाषाण स्थल से गर्तावास, हड्डी के सुई-उपकरण और कब्रों में मालिक के साथ कुत्ते दफनाने के प्रमाण मिले हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अतिथि देवो भव : कोषाध्यक्ष\n2. संगृहीता : छान्दोग्य उपनिषद\n3. अघन्या : गाय (न मारे जाने योग्य)\n4. तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु) : बृहदारण्यक उपनिषद","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: ऋग्वेद में आर्थिक समृद्धि की प्रतीक गाय को 'अघन्या' कहा गया है। (अन्य सही युग्म: अतिथि देवो भव→तैत्तिरीय उपनिषद, संगृहीता→कोषाध्यक्ष, तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु)→छान्दोग्य उपनिषद)।"},
  {"q":"[PSC/CDS युग्म पहचान — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अहं ब्रह्मास्मि : बृहदारण्यक उपनिषद\n2. गविष्टि : कोषाध्यक्ष\n3. संगृहीता : गेहूँ\n4. गोधूम : मुद्रा/मूल्य की इकाइयाँ","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: बृहदारण्यक उपनिषद में 'अहं ब्रह्मास्मि' तथा याज्ञवल्क्य-गार्गी संवाद मिलता है। (अन्य सही युग्म: गविष्टि→गायों के लिए युद्ध / खोज, संगृहीता→कोषाध्यक्ष, गोधूम→गेहूँ)।"},
  {"q":"[PSC/CDS युग्म पहचान — सिन्धु स्थल एवं नदी] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मांडा : घग्घर नदी\n2. कालीबंगा : प्रवरा नदी\n3. रोपड़ : सतलज नदी\n4. दैमाबाद : दाश्क नदी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: रोपड़ पंजाब में सतलज नदी के तट पर स्थित सैंधव स्थल था। (अन्य सही युग्म: मांडा→चिनाब नदी, कालीबंगा→घग्घर नदी, दैमाबाद→प्रवरा नदी)।"}
]);
